/* ==底栏浮动透底 + 恢复全部点击== */

/* 1. 变量系统清空默认白底与边框 */
:root {
  --input-area-bg: transparent;
  --input-area-border-top: none;
  --input-area-blur: 0px;
}

/* ===================================================
 * 修复：智能底栏浮动（平常透底，多选时自动恢复正常流防遮挡）
 * =================================================== */

/* 1. 默认平常聊天状态（未进入多选）：保持绝对浮动透底 */
.chat-detail-screen:not(:has([class*="checkbox"])) .input-area-custom {
  position: absolute !important;
  bottom: 0 !important;
  left: 0 !important;
  right: 0 !important;
  z-index: 50 !important;
  pointer-events: auto !important;

  background: transparent !important;
  border-top: none !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-sizing: border-box !important;
}

/* 2. 核心根治：一旦长按进入多选模式（左侧出现勾选圆圈），立刻解除绝对定位！
 * 恢复原生文档流，多选栏高度彻底释放，「↑ 选到这里」自然恢复在上方，绝不再被压扁重叠！
 */
.chat-detail-screen:has([class*="checkbox"]) .input-area-custom {
  position: relative !important;
  bottom: auto !important;
  left: auto !important;
  right: auto !important;
  z-index: 50 !important;
  pointer-events: auto !important;
  box-sizing: border-box !important;
}

/* 3. 强制确保内部所有行容器、输入胶囊、输入框、加号按钮 100% 能够点击 */
.chat-detail-screen .input-row-wrapper,
.chat-detail-screen .input-action-bar-custom,
.chat-detail-screen .input-box-custom,
.chat-detail-screen .input-btn-plus,
.chat-detail-screen .input-btns-right,
.chat-detail-screen .input-btns-right * {
  pointer-events: auto !important;
  cursor: pointer !important;
}

.chat-detail-screen .input-box-custom {
  cursor: text !important;
}

.chat-detail-screen .input-row-wrapper {
  background: transparent !important;
  position: relative !important;
  z-index: 2 !important;
}

/* 4. 消息区域留出底部安全距离，让消息自然穿透滑入底栏后方 */
.chat-detail-screen .chat-messages-area {
  padding-bottom: calc(var(--input-area-min-height, 56px) + env(safe-area-inset-bottom, 44px) + 79px) !important;
  box-sizing: border-box !important;
}

/* 双重保险：最后一条消息绝不被挡 */
.chat-detail-screen [data-absolute-last="true"],
.chat-detail-screen .chat-messages-area > :last-child {
  margin-bottom: 50px !important;
}

/* 5. 底栏微弱空气渐变层：确保 pointer-events: none，绝对不挡点击 */
.chat-detail-screen .input-area-custom::before {
  content: "" !important;
  position: absolute !important;
  inset: 0 !important;
  top: -16px !important;
  z-index: -1 !important;
  /* 核心：背景板绝不参与任何点击，光标与手指直接穿透给上面的按钮 */
  pointer-events: none !important;

  background: linear-gradient(
    to top,
    rgba(0, 0, 0, 0.40) 0%,
    rgba(0, 0, 0, 0.22) 35%,
    rgba(0, 0, 0, 0.08) 65%,
    rgba(0, 0, 0, 0.01) 85%,
    transparent 100%
  ) !important;

  backdrop-filter: blur(8px) saturate(120%) !important;
  -webkit-backdrop-filter: blur(8px) saturate(120%) !important;

  -webkit-mask-image: linear-gradient(
    to top,
    rgba(0, 0, 0, 0.85) 0%,
    rgba(0, 0, 0, 0.60) 35%,
    rgba(0, 0, 0, 0.20) 65%,
    transparent 90%
  ) !important;
  mask-image: linear-gradient(
    to top,
    rgba(0, 0, 0, 0.85) 0%,
    rgba(0, 0, 0, 0.60) 35%,
    rgba(0, 0, 0, 0.20) 65%,
    transparent 90%
  ) !important;
}

/* ==底栏输入胶囊压扁紧凑== */
.chat-detail-screen .input-action-bar-custom {
  min-height: 36px !important;
  max-height: 120px !important;
  padding-top: 3px !important;
