/* == 消息气泡 & 引用回复 & 头像隐藏 & 卡片排他规则== */
:root {
  --bubble-them-bg: rgba(255, 255, 255, 0.14);
  --bubble-them-color: #fff;
  --bubble-them-border: none;
  --bubble-them-shadow: none;
  --bubble-them-backdrop: blur(14px) saturate(140%);
  --bubble-them-radius: 20px;
  --bubble-them-radius-first: 20px;
  --bubble-them-radius-mid: 20px;
  --bubble-them-radius-last: 20px;

  --them-rim: linear-gradient(135deg,
    rgba(255, 255, 255, 0.55) 0%,
    rgba(255, 255, 255, 0.10) 35%,
    rgba(255, 255, 255, 0.06) 65%,
    rgba(255, 255, 255, 0.28) 100%);

  --bubble-me-bg: #2c63c8;
  --bubble-me-color: #fff;
  --bubble-me-border: none;
  --bubble-me-shadow: none;
  --bubble-me-radius: 20px;
  --bubble-me-radius-first: 20px;
  --bubble-me-radius-mid: 20px;
  --bubble-me-radius-last: 20px;
}

.bubble-them-custom,
.bubble-me-custom {
  position: relative !important;
  overflow: visible !important;
  isolation: isolate;
}

.bubble-them-custom {
  background: transparent !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
  box-shadow: none !important;
}
.bubble-them-custom::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: inherit;
  background: var(--bubble-them-bg);
  -webkit-backdrop-filter: var(--bubble-them-backdrop);
  backdrop-filter: var(--bubble-them-backdrop);
}

.bubble-them-custom::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  box-sizing: border-box;
  border: 1px solid transparent;
  border-radius: inherit;
  background: var(--them-rim) border-box;
  -webkit-mask: linear-gradient(#000 0 0) border-box, linear-gradient(#000 0 0) padding-box;
  -webkit-mask-composite: source-out;
  mask: linear-gradient(#000 0 0) border-box, linear-gradient(#000 0 0) padding-box;
  mask-composite: subtract;
}

.bubble-them-custom:not(.first):not(.mid) {
  --them-shape:
    radial-gradient(circle at 100% 100%, #000 19.5px, transparent 20px) left 0 top 0 / 20px 20px no-repeat,
    radial-gradient(circle at 0 100%, #000 19.5px, transparent 20px) right 0 top 0 / 20px 20px no-repeat,
