/* ==Apple Pay 转账卡片 == */

/* 1. 2:1 比例卡片外壳 */
.msg-transfer-card {
  position: relative !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: center !important;

  /* 严格 2:1 紧凑比例 */
  width: 170px !important;
  height: 85px !important;
  min-height: 85px !important;
  max-height: 85px !important;

  border-radius: 18px !important;
  padding: 0 !important;
  margin: 2px 0 !important;
  box-sizing: border-box !important;
  overflow: hidden !important;
}

/* 2. 核心：通透磨砂背景 + 液态水光反射高光边框 */
/* 我方：液态蓝光磨砂玻璃 */
.msg-me .msg-transfer-card {
  /* 通透水蓝半透渐变底（绝不发死发实，透出星空壁纸） */
  background: linear-gradient(
    180deg,
    rgba(104, 157, 232, 0.45) 0%,
    rgba(60, 120, 220, 0.32) 50%,
    rgba(40, 95, 195, 0.22) 100%
  ) !important;

  /* 核心磨砂：18px 水润折射 + 180% 鲜活饱和度 */
  backdrop-filter: blur(18px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(18px) saturate(180%) !important;

  /* 极细微高光反光外边框 */
  border: 0.8px solid rgba(255, 255, 255, 0.38) !important;

  /* 核心液态高光：顶端强烈水光线 + 底部水弧微折射 + 悬浮立体柔影 */
  box-shadow: 
    inset 0 1.2px 1px rgba(255, 255, 255, 0.65),       /* 顶端清晰明亮的水光线 */
    inset 0 -1px 1px rgba(255, 255, 255, 0.22),        /* 底端微透折射弧 */
    0 4px 16px rgba(0, 0, 0, 0.25) !important;         /* 3D 悬浮投影 */
}

/* 对方：液态灰光磨砂玻璃 */
.msg-them .msg-transfer-card {
  /* 苹果官方 systemGray 通透水灰底 */
  background: linear-gradient(
    180deg,
    rgba(160, 160, 168, 0.38) 0%,
    rgba(110, 110, 118, 0.26) 50%,
    rgba(80, 80, 88, 0.18) 100%
  ) !important;

  backdrop-filter: blur(18px) saturate(160%) !important;
  -webkit-backdrop-filter: blur(18px) saturate(160%) !important;

  border: 0.8px solid rgba(255, 255, 255, 0.30) !important;

  box-shadow: 
    inset 0 1.2px 1px rgba(255, 255, 255, 0.55),
    inset 0 -1px 1px rgba(255, 255, 255, 0.18),
    0 4px 16px rgba(0, 0, 0, 0.22) !important;
}

/* 3. 左上角加上「Pay」标志（原封不动保留） */
.msg-transfer-card::before {
  content: "Pay" !important;
  display: block !important;
  position: absolute !important;
  left: 14px !important;
  top: 5px !important;
  font-size: 13px !important;
  font-weight: 700 !important;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue", sans-serif !important;
  color: rgba(255, 255, 255, 0.95) !important;
  -webkit-text-fill-color: rgba(255, 255, 255, 0.95) !important;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.35) !important;
  letter-spacing: -0.3px !important;
  z-index: 5 !important;
  pointer-events: none !important;
}

/* 4. 彻底歼灭右上角红点与一切杂质（原封不动保留） */
.msg-transfer-card .msg-transfer-header,
.msg-transfer-card .msg-transfer-icon,
.msg-transfer-card .msg-transfer-label,
.msg-transfer-card .msg-transfer-subtitle,
.msg-transfer-card .msg-transfer-status-text,
.msg-transfer-card .msg-transfer-status,
.msg-transfer-card .msg-transfer-divider,
