.nuo-typing-indicator { --typing-dot-color: rgba(60, 60, 67, 0.55); }
.nuo-typing-bubble::after { filter: invert(1); opacity: 0.45; }

/* ---------- 转账卡片：对方那张改成偏深的灰，保证白字看得清 ---------- */
