  background: linear-gradient(180deg,
    rgba(110, 110, 118, 0.62) 0%, rgba(90, 90, 98, 0.52) 50%, rgba(70, 70, 78, 0.46) 100%) !important;
}

/* ---------- 长按菜单 ---------- */
.chat-detail-screen .ig-context-menu,
.chat-detail-screen .reaction-bar {
  background: rgba(255, 255, 255, 0.72) !important;
  border: 0.5px solid rgba(0, 0, 0, 0.08) !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9), 0 12px 36px rgba(0, 0, 0, 0.16) !important;
}
.chat-detail-screen .ig-menu-item {
  color: var(--light-ink) !important;
  border-bottom-color: rgba(0, 0, 0, 0.08) !important;
}
.chat-detail-screen .ig-menu-item svg {
  color: var(--light-ink) !important;
